#nullable enable
using Alba;
using Campaigns.Contracts;
using Campaigns.Slices.Campaigns;
using Microsoft.AspNetCore.Mvc;
using Shouldly;
using Xunit;

namespace Campaigns.IntegrationTests.Slices.Campaigns;

/// <summary>Pattern: command. Status: ready. A state change on a stream that already exists.</summary>
public sealed class CloseCampaignTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static string Route(Guid campaignId) => $"/campaigns/{campaignId}/close";

    /// <summary>WHEN, normalised to (ok, rule) so both outcomes assert the same way.</summary>
    private async Task<(bool Ok, string? Rule)> Close(Guid campaignId)
    {
        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new CloseCampaign(campaignId)).ToUrl(Route(campaignId));
            x.IgnoreStatusCode();
        });

        if (result.Context.Response.StatusCode == 204) return (true, null);
        return (false, (await result.ReadAsJsonAsync<ProblemDetails>())?.Title);
    }

    // an open campaign can be closed
    //   GIVEN CampaignOpened
    //   WHEN  CloseCampaign
    //   THEN  CampaignClosed
    [Fact]
    public async Task AnOpenCampaignCanBeClosed()
    {
        var campaignId = SeedData.CampaignId;
        await Given(campaignId, new CampaignOpened(campaignId, "January", SeedData.SeededAt));

        var (ok, rule) = await Close(campaignId);

        ok.ShouldBeTrue(rule);
        (await EventsFor(campaignId)).Last().ShouldBeOfType<CampaignClosed>();
    }

    // closing a closed campaign is refused
    //   GIVEN CampaignOpened, CampaignClosed
    //   WHEN  CloseCampaign
    //   THEN  error: AlreadyClosed    (enforce="aggregate")
    [Fact]
    public async Task ClosingAClosedCampaignIsRefused()
    {
        var campaignId = SeedData.CampaignId;
        await Given(campaignId,
            new CampaignOpened(campaignId, "January", SeedData.SeededAt),
            new CampaignClosed(campaignId, SeedData.SeededAt));

        var (ok, rule) = await Close(campaignId);

        ok.ShouldBeFalse();
        rule.ShouldBe("AlreadyClosed");

        // The rule holds: no second CampaignClosed. Asserting the refusal alone would pass even if the
        // append had happened anyway.
        (await EventsFor(campaignId)).OfType<CampaignClosed>().Count().ShouldBe(1);
    }
}
